import{_ as a,o as i,c as n,a2 as l}from"./chunks/framework.DV9MvnYb.js";const c=JSON.parse('{"title":"从第一篇文章开始：这个网站是怎样搭起来的","description":"记录个人网站的目标、技术选择、部署流程，以及我准备如何维护它。","frontmatter":{"title":"从第一篇文章开始：这个网站是怎样搭起来的","description":"记录个人网站的目标、技术选择、部署流程，以及我准备如何维护它。","date":"2025-05-22T00:00:00.000Z","tags":["网站","VitePress","GitHub Pages"]},"headers":[],"relativePath":"posts/2025-05-22-hello-blog.md","filePath":"posts/2025-05-22-hello-blog.md","lastUpdated":1786556769000}'),e={name:"posts/2025-05-22-hello-blog.md"};function t(p,s,h,o,r,d){return i(),n("div",null,[...s[0]||(s[0]=[l(`<p>这是这个网站的第一篇文章。与其只留下一句 “Hello, World”，不如借这个入口说明：这个网站为什么存在，它是怎样运行的，以及之后会放些什么。</p><h2 id="为什么做一个个人网站" tabindex="-1">为什么做一个个人网站 <a class="header-anchor" href="#为什么做一个个人网站" aria-label="Permalink to &quot;为什么做一个个人网站&quot;">​</a></h2><p>零散的收藏夹适合保存链接，却不适合沉淀自己的理解。聊天记录、临时笔记和代码片段也很容易在时间里失去上下文。</p><p>我希望这里能承担三件事：</p><ol><li><strong>记录学习过程</strong>：把 Rust、操作系统和 Linux 内核中的关键问题写清楚。</li><li><strong>整理可靠资料</strong>：不仅收集链接，还说明它解决什么问题、适合在哪个阶段阅读。</li><li><strong>保留长期作品</strong>：让文章使用普通 Markdown 保存，不被某个平台的编辑器或推荐算法绑住。</li></ol><h2 id="技术选择" tabindex="-1">技术选择 <a class="header-anchor" href="#技术选择" aria-label="Permalink to &quot;技术选择&quot;">​</a></h2><p>网站使用 <a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a> 构建。内容是 Markdown，界面部分由 Vue 和 CSS 完成，最后输出为静态 HTML。</p><p>这套方案很适合个人知识站：</p><ul><li>Markdown 文件可以直接进入 Git 版本管理；</li><li>不需要数据库和长期运行的服务器；</li><li>页面生成后加载简单，托管成本接近于零；</li><li>需要定制时仍然可以使用 Vue 组件。</li></ul><h2 id="从提交到上线" tabindex="-1">从提交到上线 <a class="header-anchor" href="#从提交到上线" aria-label="Permalink to &quot;从提交到上线&quot;">​</a></h2><p>源码保存在仓库的 <code>main</code> 分支。每次向 <code>main</code> 推送提交后，GitHub Actions 会自动执行以下步骤：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>push main</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>npm ci</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>npm run build</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>生成 .vitepress/dist</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>发布到 gh-pages</span></span></code></pre></div><p>因此，日常维护只需要编辑内容、在本地检查，然后提交并推送。<code>gh-pages</code> 是自动生成的发布分支，不应该手动修改。</p><h2 id="内容怎样组织" tabindex="-1">内容怎样组织 <a class="header-anchor" href="#内容怎样组织" aria-label="Permalink to &quot;内容怎样组织&quot;">​</a></h2><p>目前网站分为四部分：</p><ul><li><strong>文章</strong>：能够独立阅读的技术总结与阶段复盘；</li><li><strong>学习</strong>：按方向整理的资料和建议顺序；</li><li><strong>工具</strong>：实际有使用价值的软件与服务；</li><li><strong>留言</strong>：读者可以通过 GitHub Issues 留下问题。</li></ul><p>新增文章时，只需要在 <code>posts/</code> 下创建 Markdown 文件并填写基本信息：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">文章标题</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">一句话说明文章解决什么问题</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">date</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2026-08-12</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Rust</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">操作系统</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span></code></pre></div><p>文章首页会读取这些信息，自动按日期倒序生成列表。</p><h2 id="写作约定" tabindex="-1">写作约定 <a class="header-anchor" href="#写作约定" aria-label="Permalink to &quot;写作约定&quot;">​</a></h2><p>为了让这里不再变成另一个无人整理的收藏夹，我给内容留了几个简单约束：</p><ul><li>标题尽量描述具体问题，而不是只写一个宽泛名词；</li><li>开头说明文章适合谁、准备解决什么；</li><li>引用资料时补充自己的判断，不只粘贴链接；</li><li>尚未验证的结论明确标注，代码尽量保留运行环境；</li><li>旧文章有错误就直接修正，由 Git 保存修改历史。</li></ul><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><p>网站的样式会继续调整，但内容会优先于装饰。下一阶段准备沿着 Rust、操作系统实验和 Linux 内核阅读这条主线，把学习过程中反复遇到的问题整理成可以复用的文章。</p><p>如果你对某个主题感兴趣，或者发现页面中的错误，欢迎去<a href="/guestbook/">留言板</a>留下问题。</p>`,25)])])}const g=a(e,[["render",t]]);export{c as __pageData,g as default};
